     1	package br.com.mealta.domain;
     2	
     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	import java.time.Month;
     6	
     7	public class Pricing {
     8	    private static final BigDecimal HIGH_SEASON_FACTOR = new BigDecimal("1.20");
     9	
    10	    public Quote quote(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
    11	        BigDecimal subtotal = Money.ZERO;
    12	        int nights = 0;
    13	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    14	            subtotal = subtotal.add(nightPrice(room, night));
    15	            nights++;
    16	        }
    17	        BigDecimal discount = plan.discountOn(subtotal);
    18	        return new Quote(nights, subtotal, discount, Money.round(subtotal.subtract(discount)));
    19	    }
    20	
    21	    public BigDecimal nightPrice(Room room, LocalDate night) {
    22	        BigDecimal rate = room.nightlyRate();
    23	        return Money.round(isHighSeason(night) ? rate.multiply(HIGH_SEASON_FACTOR) : rate);
    24	    }
    25	
    26	    /** 15/12 até o fim de fevereiro, e julho inteiro. */
    27	    public boolean isHighSeason(LocalDate date) {
    28	        Month month = date.getMonth();
    29	        return month == Month.JANUARY || month == Month.FEBRUARY || month == Month.JULY
    30	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
    31	    }
    32	}
