     9	public record Receipt(String title, long reservationId, String guestName, String guestCpf, int roomNumber,
    10	                      RoomType roomType, LocalDate checkIn, LocalDate checkOut, int nights,
    11	                      BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
    12	
    13	    public static final String TITLE = "Comprovante de reserva";
    14	    private static final DateTimeFormatter DATE = DateTimeFormatter.ofPattern("dd/MM/yyyy");
    15	
    16	    public static Receipt of(Reservation r, Room room) {
    17	        return new Receipt(TITLE, r.id(), r.guestName(), r.guestCpf(), room.number(), room.type(),
    18	                r.checkInDate(), r.checkOutDate(), r.nights(), r.subtotal(), r.discount(), r.total());
    19	    }
    20	
    21	    public String toText() {
    22	        List<String> lines = new ArrayList<>();
    23	        lines.add(title + " nº " + reservationId);
    24	        lines.add("Hóspede: " + guestName + " (CPF " + guestCpf + ")");
    25	        lines.add("Quarto: " + roomNumber + " (" + roomType + ")");
    26	        lines.add("Entrada: " + DATE.format(checkIn) + " | Saída: " + DATE.format(checkOut) + " | "
    27	                + nights + (nights == 1 ? " diária" : " diárias"));
    28	        lines.add("Diárias: " + Money.format(subtotal));
    29	        if (discount.signum() > 0) {
    30	            lines.add("Desconto: " + Money.format(discount));
    31	        }
    32	        lines.add("Total: " + Money.format(total));
    33	        return String.join("\n", lines);
    34	    }
    35	}
