     2	
     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	import java.time.temporal.ChronoUnit;
     6	
     7	public class Reservation {
     8	    private Long id;
     9	    private final int roomNumber;
    10	    private final String guestName;
    11	    private final String guestEmail;
    12	    private final String guestCpf;
    13	    private final LocalDate checkIn;
    14	    private final LocalDate checkOut;
    15	    private final int guests;
    16	    private final RatePlan ratePlan;
    17	    private final BigDecimal subtotal;
    18	    private final BigDecimal discount;
    19	    private final BigDecimal total;
    20	    private ReservationStatus status;
    21	    private BigDecimal amountPaid;
    22	    private BigDecimal refund;
    23	
    24	    public Reservation(Long id, int roomNumber, String guestName, String guestEmail, String guestCpf,
    25	                       LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan,
    26	                       BigDecimal subtotal, BigDecimal discount, BigDecimal total,
    27	                       ReservationStatus status, BigDecimal amountPaid, BigDecimal refund) {
    28	        this.id = id;
    29	        this.roomNumber = roomNumber;
    30	        this.guestName = guestName;
    31	        this.guestEmail = guestEmail;
    32	        this.guestCpf = guestCpf;
    33	        this.checkIn = checkIn;
    34	        this.checkOut = checkOut;
    35	        this.guests = guests;
    36	        this.ratePlan = ratePlan;
    37	        this.subtotal = subtotal;
    38	        this.discount = discount;
    39	        this.total = total;
    40	        this.status = status;
    41	        this.amountPaid = amountPaid;
    42	        this.refund = refund;
    43	    }
    44	
    45	    public static Reservation pending(int roomNumber, String guestName, String guestEmail, String guestCpf,
    46	                                      LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan,
    47	                                      Quote quote) {
    48	        return new Reservation(null, roomNumber, guestName, guestEmail, guestCpf, checkIn, checkOut, guests,
    49	                ratePlan, quote.subtotal(), quote.discount(), quote.total(),
    50	                ReservationStatus.PENDING, Money.ZERO, null);
    51	    }
    52	
    53	    public void confirm() {
    54	        moveTo(ReservationStatus.CONFIRMED);
    55	        amountPaid = total;
    56	    }
    57	
    58	    public void checkIn() {
    59	        moveTo(ReservationStatus.CHECKED_IN);
    60	    }
    61	
    62	    public void checkOut() {
    63	        moveTo(ReservationStatus.CHECKED_OUT);
    64	    }
    65	
    66	    public void cancel() {
    67	        moveTo(ReservationStatus.CANCELLED);
    68	        refund = ratePlan.refundOf(amountPaid);
    69	    }
    70	
    71	    private void moveTo(ReservationStatus next) {
    72	        if (!status.canGoTo(next)) {
    73	            throw new PousadaException(ErrorCode.OPERATION_NOT_ALLOWED,
    74	                    "Operação não permitida para reserva com status " + status);
    75	        }
    76	        status = next;
    77	    }
    78	
    79	    public boolean isPaid() {
    80	        return status.isPaid();
    81	    }
    82	
    83	    /** O dinheiro que fica com a pousada: o que foi pago menos o que foi devolvido. */
    84	    public BigDecimal keptAmount() {
    85	        return refund == null ? amountPaid : Money.round(amountPaid.subtract(refund));
    86	    }
    87	
    88	    public boolean retainsMoney() {
    89	        return keptAmount().signum() > 0;
    90	    }
    91	
    92	    public boolean occupies(LocalDate night) {
    93	        return !night.isBefore(checkIn) && night.isBefore(checkOut);
    94	    }
    95	
    96	    public int nights() {
    97	        return (int) ChronoUnit.DAYS.between(checkIn, checkOut);
    98	    }
