     1	package br.com.mealta.domain;
     2	
     3	import java.util.Set;
     4	
     5	public enum ReservationStatus {
     6	    PENDING, CONFIRMED, CHECKED_IN, CHECKED_OUT, CANCELLED;
     7	
     8	    public boolean canGoTo(ReservationStatus next) {
     9	        return allowedNext().contains(next);
    10	    }
    11	
    12	    /** Reserva que já foi paga e não foi cancelada. */
    13	    public boolean isPaid() {
    14	        return this == CONFIRMED || this == CHECKED_IN || this == CHECKED_OUT;
    15	    }
    16	
    17	    private Set<ReservationStatus> allowedNext() {
    18	        return switch (this) {
    19	            case PENDING -> Set.of(CONFIRMED, CANCELLED);
    20	            case CONFIRMED -> Set.of(CHECKED_IN, CANCELLED);
    21	            case CHECKED_IN -> Set.of(CHECKED_OUT);
    22	            case CHECKED_OUT, CANCELLED -> Set.of();
    23	        };
    24	    }
    25	}
