     9	public class ReservationService {
    10	    private final ReservationRepository reservations;
    11	    private final MessageLog messages;
    12	    private final Transactor tx;
    13	    private final RoomCatalog rooms;
    14	    private final Pricing pricing;
    15	
    16	    public ReservationService(ReservationRepository reservations, MessageLog messages, Transactor tx,
    17	                              RoomCatalog rooms, Pricing pricing) {
    18	        this.reservations = reservations;
    19	        this.messages = messages;
    20	        this.tx = tx;
    21	        this.rooms = rooms;
    22	        this.pricing = pricing;
    23	    }
    24	
    25	    public Reservation create(CreateReservation cmd) {
    26	        if (!cmd.checkOut().isAfter(cmd.checkIn())) {
    27	            throw new PousadaException(ErrorCode.INVALID_REQUEST, "A saída deve ser depois da entrada");
    28	        }
    29	        if (cmd.guests() < 1) {
    30	            throw new PousadaException(ErrorCode.INVALID_REQUEST, "É preciso ao menos um hóspede");
    31	        }
    32	        Room room = rooms.require(cmd.roomNumber());
    33	        if (cmd.guests() > room.capacity()) {
    34	            throw new PousadaException(ErrorCode.CAPACITY_EXCEEDED,
    35	                    "O quarto " + room.number() + " comporta até " + room.capacity() + " hóspedes");
    36	        }
    37	        Quote quote = pricing.quote(room, cmd.checkIn(), cmd.checkOut(), cmd.ratePlan());
    38	        return tx.run(() -> {
    39	            reservations.lockRoom(room.number());
    40	            if (reservations.hasActiveOverlap(room.number(), cmd.checkIn(), cmd.checkOut())) {
    41	                throw new PousadaException(ErrorCode.ROOM_UNAVAILABLE,
    42	                        "O quarto " + room.number() + " já está reservado em alguma dessas noites");
    43	            }
    44	            return reservations.save(Reservation.pending(room.number(), cmd.guestName(), cmd.guestEmail(),
    45	                    cmd.guestCpf(), cmd.checkIn(), cmd.checkOut(), cmd.guests(), cmd.ratePlan(), quote));
    46	        });
    47	    }
    48	
    49	    public Reservation get(long id) {
    50	        return reservations.findById(id).orElseThrow(() -> notFound(id));
    51	    }
    52	
    53	    public Reservation confirm(long id) {
    54	        return change(id, reservation -> {
    55	            reservation.confirm();
    56	            messages.add(ReservationMessages.confirmation(reservation, receiptOf(reservation)));
    57	        });
    58	    }
    59	
    60	    public Reservation cancel(long id) {
    61	        return change(id, Reservation::cancel);
    62	    }
    63	
    64	    public Reservation checkIn(long id) {
    65	        return change(id, Reservation::checkIn);
    66	    }
    67	
    68	    public Receipt checkOut(long id) {
    69	        return receiptOf(change(id, Reservation::checkOut));
    70	    }
    71	
    72	    /** Segunda via: só existe para reserva paga. */
    73	    public Receipt document(long id) {
    74	        Reservation reservation = get(id);
    75	        if (!reservation.isPaid()) {
    76	            throw new PousadaException(ErrorCode.OPERATION_NOT_ALLOWED,
    77	                    "Só há comprovante para reserva paga");
    78	        }
    79	        return receiptOf(reservation);
    80	    }
    81	
    82	    private Reservation change(long id, Consumer<Reservation> operation) {
    83	        return tx.run(() -> {
    84	            Reservation reservation = reservations.lockById(id).orElseThrow(() -> notFound(id));
    85	            operation.accept(reservation);
    86	            return reservations.save(reservation);
    87	        });
    88	    }
    89	
    90	    private Receipt receiptOf(Reservation reservation) {
    91	        return Receipt.of(reservation, rooms.require(reservation.roomNumber()));
    92	    }
    93	
    94	    private static PousadaException notFound(long id) {
    95	        return new PousadaException(ErrorCode.RESERVATION_NOT_FOUND, "Reserva " + id + " não existe");
    96	    }
    97	}
