    30	                    LocalDate night = date(raw);
    31	                    return new OccupancyReport(night, reservations.paidOccupying(night), rooms);
    32	                }),
    33	                new ReportDefinition("revenue", "month", raw -> {
    34	                    YearMonth month = month(raw);
    35	                    return new RevenueReport(month, reservations.startingIn(month));
    36	                }),
    37	                new ReportDefinition("tourism-tax", "month", raw -> {
    38	                    YearMonth month = month(raw);
