    47	    private static LocalDate date(String raw) {
    48	        try {
    49	            return LocalDate.parse(raw);
    50	        } catch (DateTimeParseException | NullPointerException e) {
    51	            throw new PousadaException(ErrorCode.INVALID_REQUEST, "Data inválida, use AAAA-MM-DD");
    52	        }
    53	    }
    54	
    55	    private static YearMonth month(String raw) {
    56	        try {
    57	            if (raw == null || !raw.matches("\\d{4}-\\d{2}")) {
    58	                throw new DateTimeParseException("formato", String.valueOf(raw), 0);
    59	            }
    60	            return YearMonth.parse(raw);
    61	        } catch (DateTimeParseException e) {
    62	            throw new PousadaException(ErrorCode.INVALID_REQUEST, "Mês inválido, use AAAA-MM");
    63	        }
    64	    }
    65	}
