     1	package br.com.mealta.store;
     2	
     3	import com.zaxxer.hikari.HikariConfig;
     4	import com.zaxxer.hikari.HikariDataSource;
     5	
     6	import java.sql.Connection;
     7	import java.sql.SQLException;
     8	import java.util.function.Supplier;
     9	
    10	/** Pool de conexões do PostgreSQL e transações presas à thread que as abriu. */
    11	public class Database implements Transactor, AutoCloseable {
    12	    @FunctionalInterface
    13	    public interface SqlWork<T> {
    14	        T apply(Connection connection) throws SQLException;
    15	    }
    16	
    17	    private final HikariDataSource pool;
    18	    private final ThreadLocal<Connection> current = new ThreadLocal<>();
    19	
    20	    public Database(String url, String user, String password) {
    21	        HikariConfig config = new HikariConfig();
    22	        config.setJdbcUrl(url);
    23	        config.setUsername(user);
    24	        config.setPassword(password);
    25	        config.setMaximumPoolSize(10);
    26	        config.setInitializationFailTimeout(60_000);
    27	        this.pool = new HikariDataSource(config);
    28	    }
    29	
    30	    /** Usa a conexão da transação em curso; sem transação, pega uma só para esta chamada. */
    31	    public <T> T withConnection(SqlWork<T> work) {
    32	        Connection inTransaction = current.get();
    33	        try {
    34	            if (inTransaction != null) {
    35	                return work.apply(inTransaction);
    36	            }
    37	            try (Connection connection = pool.getConnection()) {
    38	                return work.apply(connection);
    39	            }
    40	        } catch (SQLException e) {
    41	            throw new IllegalStateException("Erro no banco de dados", e);
    42	        }
    43	    }
    44	
    45	    @Override
    46	    public <T> T run(Supplier<T> work) {
    47	        if (current.get() != null) {
    48	            return work.get();
    49	        }
    50	        try (Connection connection = pool.getConnection()) {
    51	            connection.setAutoCommit(false);
    52	            current.set(connection);
    53	            try {
    54	                T result = work.get();
    55	                connection.commit();
    56	                return result;
    57	            } catch (RuntimeException | Error e) {
    58	                connection.rollback();
    59	                throw e;
    60	            } finally {
    61	                current.remove();
    62	            }
    63	        } catch (SQLException e) {
    64	            throw new IllegalStateException("Erro no banco de dados", e);
    65	        }
    66	    }
    67	
    68	    @Override
    69	    public void close() {
    70	        pool.close();
    71	    }
    72	}
