    32	            if (r.id() == null) {
    33	                try (PreparedStatement ps = c.prepareStatement("""
    34	                        INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, check_in,
    35	                            check_out, guests, rate_plan, subtotal, discount, total, status, amount_paid, refund)
    36	                        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""", Statement.RETURN_GENERATED_KEYS)) {
    37	                    ps.setInt(1, r.roomNumber());
    38	                    ps.setString(2, r.guestName());
