    48	                    ps.setString(12, r.status().name());
    49	                    ps.setBigDecimal(13, r.amountPaid());
    50	                    ps.setBigDecimal(14, r.refund());
    51	                    ps.executeUpdate();
    52	                    try (ResultSet keys = ps.getGeneratedKeys()) {
    53	                        keys.next();
    54	                        r.assignId(keys.getLong("id"));
    55	                    }
    56	                }
    57	            } else {
    58	                try (PreparedStatement ps = c.prepareStatement(
    59	                        "UPDATE reservations SET status = ?, amount_paid = ?, refund = ? WHERE id = ?")) {
    60	                    ps.setString(1, r.status().name());
    61	                    ps.setBigDecimal(2, r.amountPaid());
    62	                    ps.setBigDecimal(3, r.refund());
