   128	        return db.withConnection(c -> {
   129	            try (PreparedStatement ps = c.prepareStatement(sql)) {
   130	                for (int i = 0; i < params.length; i++) {
   131	                    ps.setObject(i + 1, params[i]);
   132	                }
   133	                try (ResultSet rs = ps.executeQuery()) {
