=== src/main/java/br/com/mealta/report/CsvRenderer.java
     1	package br.com.mealta.report;
     2	
     3	import java.util.ArrayList;
     4	import java.util.List;
     5	
     6	/** O formato de todos os relatórios: título, cabeçalho, linhas e total. */
     7	public class CsvRenderer {
     8	    private static final String HOTEL = "Pousada Maré Alta";
     9	
    10	    public String render(Report report) {
    11	        List<List<String>> lines = new ArrayList<>();
    12	        lines.add(List.of(HOTEL, report.name(), report.period()));
    13	        lines.add(report.columns());
    14	        lines.addAll(report.rows());
    15	        lines.add(report.total());
    16	        StringBuilder csv = new StringBuilder();
    17	        for (List<String> line : lines) {
    18	            csv.append(String.join(",", line)).append('\n');
