   109	    @Override
   110	    public List<Reservation> startingIn(YearMonth month) {
   111	        return queryList("SELECT " + COLUMNS + " FROM reservations WHERE check_in >= ? AND check_in < ? "
   112	                        + "ORDER BY check_in, id",
   113	                Date.valueOf(month.atDay(1)), Date.valueOf(month.plusMonths(1).atDay(1)));
   114	    }
   115	
   116	    @Override
   117	    public List<Reservation> paidOccupying(LocalDate night) {
   118	        return queryList("SELECT " + COLUMNS + " FROM reservations WHERE " + PAID
   119	                        + " AND check_in <= ? AND check_out > ? ORDER BY room_number, id",
   120	                Date.valueOf(night), Date.valueOf(night));
