    22	
    23	    private final Database db;
    24	
    25	    public PgReservationRepository(Database db) {
    26	        this.db = db;
    27	    }
    28	
    29	    @Override
    30	    public Reservation save(Reservation r) {
    31	        return db.withConnection(c -> {
    32	            if (r.id() == null) {
    33	                try (PreparedStatement ps = c.prepareStatement("""
    34	                        INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, check_in,
    35	                            check_out, guests, rate_plan, subtotal, discount, total, status, amount_paid, refund)
    36	                        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""", Statement.RETURN_GENERATED_KEYS)) {
    37	                    ps.setInt(1, r.roomNumber());
    38	                    ps.setString(2, r.guestName());
    39	                    ps.setString(3, r.guestEmail());
    40	                    ps.setString(4, r.guestCpf());
    41	                    ps.setDate(5, Date.valueOf(r.checkInDate()));
    42	                    ps.setDate(6, Date.valueOf(r.checkOutDate()));
    43	                    ps.setInt(7, r.guests());
    44	                    ps.setString(8, r.ratePlan().name());
    45	                    ps.setBigDecimal(9, r.subtotal());
    46	                    ps.setBigDecimal(10, r.discount());
    47	                    ps.setBigDecimal(11, r.total());
    48	                    ps.setString(12, r.status().name());
    49	                    ps.setBigDecimal(13, r.amountPaid());
    50	                    ps.setBigDecimal(14, r.refund());
    51	                    ps.executeUpdate();
    52	                    try (ResultSet keys = ps.getGeneratedKeys()) {
    53	                        keys.next();
    54	                        r.assignId(keys.getLong("id"));
    55	                    }
    56	                }
    57	            } else {
    58	                try (PreparedStatement ps = c.prepareStatement(
    59	                        "UPDATE reservations SET status = ?, amount_paid = ?, refund = ? WHERE id = ?")) {
    60	                    ps.setString(1, r.status().name());
    61	                    ps.setBigDecimal(2, r.amountPaid());
    62	                    ps.setBigDecimal(3, r.refund());
    63	                    ps.setLong(4, r.id());
    64	                    ps.executeUpdate();
    65	                }
    66	            }
    67	            return r;
    68	        });
    69	    }
