    73	        return queryOne("SELECT " + COLUMNS + " FROM reservations WHERE id = ?", id);
    74	    }
    75	
    76	    @Override
    77	    public Optional<Reservation> lockById(long id) {
    78	        return queryOne("SELECT " + COLUMNS + " FROM reservations WHERE id = ? FOR UPDATE", id);
    79	    }
