    81	    @Override
    82	    public void lockRoom(int roomNumber) {
    83	        db.withConnection(c -> {
    84	            try (PreparedStatement ps = c.prepareStatement("SELECT pg_advisory_xact_lock(?)")) {
    85	                ps.setLong(1, roomNumber);
