    87	            }
    88	            return null;
    89	        });
    90	    }
    91	
    92	    @Override
    93	    public boolean hasActiveOverlap(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
    94	        return db.withConnection(c -> {
    95	            try (PreparedStatement ps = c.prepareStatement("""
    96	                    SELECT 1 FROM reservations
    97	                    WHERE room_number = ? AND status <> 'CANCELLED' AND check_in < ? AND check_out > ?
    98	                    LIMIT 1""")) {
    99	                ps.setInt(1, roomNumber);
   100	                ps.setDate(2, Date.valueOf(checkOut));
   101	                ps.setDate(3, Date.valueOf(checkIn));
   102	                try (ResultSet rs = ps.executeQuery()) {
   103	                    return rs.next();
   104	                }
   105	            }
   106	        });
   107	    }
   108	
   109	    @Override
   110	    public List<Reservation> startingIn(YearMonth month) {
   111	        return queryList("SELECT " + COLUMNS + " FROM reservations WHERE check_in >= ? AND check_in < ? "
   112	                        + "ORDER BY check_in, id",
   113	                Date.valueOf(month.atDay(1)), Date.valueOf(month.plusMonths(1).atDay(1)));
   114	    }
   115	
   116	    @Override
   117	    public List<Reservation> paidOccupying(LocalDate night) {
   118	        return queryList("SELECT " + COLUMNS + " FROM reservations WHERE " + PAID
   119	                        + " AND check_in <= ? AND check_out > ? ORDER BY room_number, id",
   120	                Date.valueOf(night), Date.valueOf(night));
   121	    }
   122	
   123	    private Optional<Reservation> queryOne(String sql, Object... params) {
   124	        return queryList(sql, params).stream().findFirst();
   125	    }
   126	
   127	    private List<Reservation> queryList(String sql, Object... params) {
   128	        return db.withConnection(c -> {
   129	            try (PreparedStatement ps = c.prepareStatement(sql)) {
   130	                for (int i = 0; i < params.length; i++) {
   131	                    ps.setObject(i + 1, params[i]);
   132	                }
   133	                try (ResultSet rs = ps.executeQuery()) {
   134	                    List<Reservation> found = new ArrayList<>();
   135	                    while (rs.next()) {
   136	                        found.add(read(rs));
   137	                    }
   138	                    return found;
   139	                }
   140	            }
   141	        });
   142	    }
   143	
   144	    private static Reservation read(ResultSet rs) throws SQLException {
   145	        return new Reservation(rs.getLong("id"), rs.getInt("room_number"), rs.getString("guest_name"),
   146	                rs.getString("guest_email"), rs.getString("guest_cpf"),
   147	                rs.getDate("check_in").toLocalDate(), rs.getDate("check_out").toLocalDate(),
   148	                rs.getInt("guests"), RatePlan.valueOf(rs.getString("rate_plan")),
   149	                rs.getBigDecimal("subtotal"), rs.getBigDecimal("discount"), rs.getBigDecimal("total"),
   150	                ReservationStatus.valueOf(rs.getString("status")),
   151	                rs.getBigDecimal("amount_paid"), rs.getBigDecimal("refund"));
   152	    }
   153	}
