172	
173	import java.time.LocalDate;
174	import java.time.YearMonth;
175	import java.util.ArrayList;
176	import java.util.Comparator;
177	import java.util.List;
178	import java.util.Optional;
179	import java.util.function.Supplier;
180	
181	/** Implementação em memória das portas de armazenamento, só para os testes. */
182	public class InMemoryStore implements ReservationRepository, MessageLog, Transactor {
183	    private final List<Reservation> reservations = new ArrayList<>();
184	    private final List<Message> messages = new ArrayList<>();
185	
186	    @Override
187	    public synchronized Reservation save(Reservation r) {
188	        if (r.id() == null) {
189	            r.assignId(reservations.size() + 1);
190	            reservations.add(r);
191	        }
192	        return r;
193	    }
194	
195	    @Override
196	    public synchronized Optional<Reservation> findById(long id) {
197	        return reservations.stream().filter(r -> r.id() == id).findFirst();
198	    }
199	
200	    @Override
201	    public Optional<Reservation> lockById(long id) {
202	        return findById(id);
203	    }
204	
205	    @Override
206	    public void lockRoom(int roomNumber) {
207	    }
208	
209	    @Override
210	    public synchronized boolean hasActiveOverlap(int room, LocalDate in, LocalDate out) {
211	        return reservations.stream().anyMatch(r -> r.roomNumber() == room
212	                && r.status() != br.com.mealta.domain.ReservationStatus.CANCELLED
213	                && r.checkInDate().isBefore(out) && r.checkOutDate().isAfter(in));
214	    }
215	
216	    @Override
217	    public synchronized List<Reservation> startingIn(YearMonth month) {
218	        return reservations.stream().filter(r -> YearMonth.from(r.checkInDate()).equals(month))
219	                .sorted(Comparator.comparing(Reservation::checkInDate).thenComparing(Reservation::id)).toList();
220	    }
221	
222	    @Override
223	    public synchronized List<Reservation> paidOccupying(LocalDate night) {
224	        return reservations.stream().filter(r -> r.isPaid() && r.occupies(night))
225	                .sorted(Comparator.comparingInt(Reservation::roomNumber)).toList();
226	    }
227	
228	    @Override
229	    public synchronized Message add(Message m) {
230	        Message saved = new Message((long) messages.size() + 1, m.channel(), m.to(), m.subject(), m.body());
231	        messages.add(saved);
232	        return saved;
233	    }
234	
235	    @Override
236	    public synchronized List<Message> all() {
237	        return List.copyOf(messages);
238	    }
239	
240	    @Override
241	    public <T> T run(Supplier<T> work) {
242	        return work.get();
243	    }
244	}

